class Solution {
    public int minOperations(int[] nums){
        int n=nums.length;
        Arrays.sort(nums);
        int[] unique=new int[n];
        int size=0;
        for(int value:nums)if(size==0||unique[size-1]!=value)unique[size++]=value;
        int left=0,maximum=0;
        for(int right=0;right<size;right++){
            while(unique[right]>=unique[left]+n)left++;
            maximum=Math.max(maximum,right-left+1);
        }
        return n-maximum;
    }
}

code.kotlin:
class Solution {
    fun minOperations(nums:IntArray):Int{
        val n=nums.size;
        nums.sort();
        val unique=nums.distinct();
        var left=0;
        var maximum=0;
        for(right in unique.indices){
            while(unique[right]>=unique[left]+n)left++;
            maximum=maxOf(maximum,right-left+1)
        };
        return n-maximum
    }
}

